import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';
import { ArchitectureVisual } from '@/components/architecture-visual';
export function PageSections({label,title,intro,sections}:{label:string;title:string;intro:string;sections:{title:string;text:string}[]}){return <><section className="page-hero dark-section"><span className="eyebrow">MINDTEL / {label.toUpperCase()}</span><h1>{title}</h1><p>{intro}</p><span className="page-hero-index">PURPOSE → POSSIBILITY</span></section><section className="section editorial-sections">{sections.map((s,i)=><article className="editorial-row reveal" key={s.title}><span className="eyebrow">0{i+1} / {label.toUpperCase()}</span><h2>{s.title}</h2><p>{s.text}</p></article>)}</section><section className="section dark-section connected-section"><div><span className="eyebrow">THE BIGGER PICTURE</span><h2>Every part.<br/>Working together.</h2><p>Strategy, design and engineering belong in the same conversation. We connect them around the outcome your business needs.</p><Link className="underlined-link" to="/services">Explore our capabilities <ArrowUpRight size={18}/></Link></div><ArchitectureVisual variant={1}/></section></>}
